NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paulus, Silvanus en Timóteus, aan de kerk der Tessalonicenzen, in God den Vader en in den Heer Jesus Christus: Genade en vrede zij u.',
        2: 'Steeds danken we God voor u allen, zo dikwijls we u herdenken in onze gebeden.',
        3: 'Zonder ophouden toch zijn we voor God, onzen Vader, uw werkdadig geloof indachtig, uw zwoegende liefde, uw geduldige hoop op onzen Heer Jesus Christus.',
        4: 'Van God geliefde broeders, van uw uitverkiezing zijn we overtuigd.',
        5: 'Want ons Evangelie is niet tot u gekomen door woord alleen, maar ook met kracht, met den heiligen Geest, en met grote beslistheid; gij weet toch nog wel, hoe we om uwentwil onder u zijn opgetreden.',
        6: 'En gij, van uw kant, zijt navolgers geworden van ons en van den Heer, door onder veel wederwaardigheden met een blijdschap van den heiligen Geest het woord te aanvaarden;',
        7: 'zodat gij een voorbeeld werdt voor alle gelovigen in Macedonië en Achaja.',
        8: 'Want door u kreeg het woord des Heren een goede naam niet slechts in Macedonië en Achaja, maar in iedere plaats kwam uw geloof in God aan de dag. Ik had dus niet nodig, daarover te spreken;',
        9: 'want uit eigen beweging vertelde men van ons: hoe wij onder u zijn opgetreden; en hoe gij u van de afgoden tot God hebt bekeerd, om den levenden en waarachtigen God te dienen,',
        10: 'en om uit de hemel zijn Zoon te verwachten, dien Hij van de doden heeft opgewekt: Jesus, die ons verlost van de komende Toorn.',
    },
    2: {
        1: 'Broeders, zelf weet gij toch wel, dat ons optreden onder u niet zonder vrucht is geweest.',
        2: 'Want ofschoon we in Filippi, zoals u bekend is, veel lijden en smaad hadden verduurd, hebben we toch door onzen God de moed gehad, onder heftige tegenstand Gods Evangelie aan u te verkondigen.',
        3: 'Ons troostwoord had dan ook niets te doen met dwaling, onzuivere bedoeling of bedrog;',
        4: 'maar we verkondigen het Evangelie, zoals God ons daartoe waardig keurde, en zoals Hij het ons heeft toevertrouwd: niet om te behagen aan mensen maar aan God, die onze harten beproeft.',
        5: 'Nooit traden we met vleitaal op, gij weet het; noch met hebzuchtige bedoelingen, God is mijn getuige.',
        6: 'We zochten niet de eer van mensen, van u noch van anderen.',
        7: 'Als apostelen van Christus hadden we ons kunnen doen gelden, maar onder u zijn we minzaam geweest. Zoals een voedster haar kinderen koestert,',
        8: 'zó hebben wij naar u gesmacht, en was het ons een groot genot, u niet alleen Gods Evangelie, maar ook ons eigen leven te schenken, omdat gij ons zo dierbaar waart.',
        9: 'Broeders, gij herinnert u toch ons werken en slaven; we hebben u Gods Evangelie verkondigd, zwoegende nacht en dag, om niemand van u tot last te zijn.',
        10: 'Gij zijt getuigen, en God ook, hoe heilig, rechtschapen en onberispelijk we ons onder u, gelovigen, hebben gedragen.',
        11: 'Gij weet het ook, hoe we, als een vader het zijn kinderen doet, ieder van u',
        12: 'hebben vermaand, bemoedigd, bezworen, een leven te leiden welgevallig aan God, die u roept tot zijn rijk en zijn glorie.',
        13: 'En daarom brengen ook wij dank aan God zonder einde, omdat gij het woord van God, door ons gepreekt, hebt aanvaard, en ook ter harte genomen, niet als het woord van mensen, maar, wat het in werkelijkheid is, als het woord van God, dat ook in u werkt, wanneer gij gelooft.',
        14: 'Broeders, in Christus Jesus immers zijt gij navolgers geworden van de gemeenten Gods in Judea, omdat gij van uw eigen stamgenoten hetzelfde hebt verduurd, als zij van de Joden,',
        15: 'die den Heer Jesus en de profeten hebben gedood en ook ons hebben vervolgd; Gode niet welgevallig, alle mensen vijandig,',
        16: 'verhinderen ze ons, tot de heidenen te spreken, om hen te redden. Zo maken ze in ieder opzicht de maat hunner zonden vol; dan komt de Toorn over hen ten einde toe.',
        17: 'Broeders, voor een korte tijd waren we van u verweesd naar het oog, maar niet naar het hart; met des te groter verlangen hebben we ons best gedaan, u weer te zien.',
        18: 'Ik, Paulus zelf, wilde dus wel naar u heen gaan, éénmaal, tweemaal zelfs; maar de satan heeft het ons belet.',
        19: 'Want wie anders dan gij is onze hoop, on e vreugde, onze gloriekroon voor het aanschijn van Jesus, onzen Heer, bij zijn komst?',
        20: 'Inderdaad, onze glorie en vreugde zijt gij!',
    },
    3: {
        1: 'Daar we het dus niet langer meer konden uithouden, gaven we er de voorkeur aan, alleen in Athene achter te blijven,',
        2: 'en zonden we Timóteus, onzen broeder en Gods dienaar in het Evangelie van Christus, om u te versterken, en u te bemoedigen in uw geloof,',
        3: 'opdat niemand door deze wederwaardigheden aan het wankelen zou worden gebracht. Zelf weet gij toch wel, dat dergelijke dingen ons te wachten staan;',
        4: 'bovendien hebben we, toen we bij u waren, u toch vooruit gezegd, dat we wederwaardigheden zouden te verduren hebben; en zo is het ook gebeurd, als gij weet.',
        5: 'Omdat ik het dus niet langer meer uithield, heb ik er hem op afgezonden, om te weten, hoe het staat met uw geloof: de bekoorder mocht u eens hebben verleid, en onze arbeid vergeefs zijn geweest.',
        6: 'Zo juist is Timóteus van u teruggekeerd, en heeft ons goede tijding gebracht van uw geloof en van uw liefde tot ons, en hoe gij steeds een goede herinnering aan ons bewaart en vurig verlangt, ons weer te zien, zoals wij u.',
        7: 'Daarom broeders, zijn we bij al onze nood en druk door uw geloof met troost over u vervuld;',
        8: 'want nu leven we op, zo gij maar vast staat in den Heer.',
        9: 'Hoe kunnen we God genoeg om u danken voor al de vreugde, waarmee we ons over u verblijden voor het aanschijn van onzen God.',
        10: 'Vurig bidden we nacht en dag, om u te mogen weerzien, en de leemten aan te vullen in uw geloof.',
        11: 'Moge dan onze God en Vader zelf en onze Heer Jesus òns de weg naar u banen;',
        12: 'moge de Heer ú echter vervullen en doen overvloeien van liefde tot elkander en tot iedereen, zoals wij ze hebben tot u.',
        13: 'Zo make Hij uw harten sterk en onberispelijk in heiligheid voor het aanschijn van God, onzen Vader, bij de komst van onzen Heer Jesus, met al zijn heiligen.',
    },
    4: {
        1: 'Overigens broeders, bidden en smeken we u in den Heer Jesus, dat gij nog meer moogt uitmunten in uw levenswandel en in het behagen aan God, zoals gij dat van ons hebt geleerd, en zoals gij dat feitelijk reeds betracht.',
        2: 'Gij weet toch wel, welke voorschriften we u uit naam van den Heer Jesus hebben gegeven.',
        3: 'Want dit is Gods wil, uw heiliging: dat gij u namelijk van ontucht onthoudt;',
        4: 'dat ieder van u zijn eigen vrouw weet te verwerven in heiligheid en eerbaarheid,',
        5: 'niet in hartstochtelijke begeerlijkheid, zoals de heidenen, die God niet kennen;',
        6: 'dat niemand zich te buiten gaat, en in deze aangelegenheid zijn broeder bedriegt. Want de Heer is de Wreker van al deze dingen, zoals we het vroeger hebben gezegd en voortdurend betuigd.',
        7: 'Want God heeft ons niet tot onreinheid geroepen, maar tot heiligheid.',
        8: 'Wie dit dus veracht, veracht niet een mens, maar God zelf, die ook aan u zijn heiligen Geest heeft geschonken.',
        9: 'Over de broederliefde is het niet nodig, u te schrijven. Want zelf hebt gij van God geleerd, elkander lief te hebben; en gij doet het ook tegenover alle broeders in heel Macedonië.',
        10: 'Maar we vermanen u, broeders, om nog meer uit te munten,',
        11: 'en er zelfs een eer in te stellen, om rustig te leven, u met uw eigen zaken te bemoeien, en zelf de handen aan het werk te slaan, zoals we u dat geboden hebben.',
        12: 'Zo toch gedraagt gij u behoorlijk voor hen, die buiten staan, en hebt gij van niemand iets nodig.',
        13: 'Broeders, wij willen u niet in onwetendheid laten over hen die ontslapen zijn, opdat gij niet treurt als de anderen, die geen hoop meer bezitten.',
        14: 'Want zo wij geloven, dat Jesus gestorven is en verrezen, dan geloven wij ook, dat God hen, die in Jesus ontsliepen, zal terugvoeren met Hem.',
        15: 'Want dit zeggen wij u op ‘s Heren woord: Wij die leven en achter blijven tot ‘s Heren komst, wij zullen de ontslapenen zeer zeker niet vóór gaan.',
        16: 'Want op een teken, op het geroep van den Aartsengel en de bazuinstoot van God, zal de Heer zelf uit de hemel nederdalen, en allereerst zullen zij verrijzen, die stierven in Christus;',
        17: 'eerst dan zullen wij, die leven en achterblijven, tezamen met hen worden weggevoerd op de wolken, den Heer tegemoet in de lucht. En zó zullen wij altijd bij den Heer blijven.',
        18: 'Vertroost dus elkander met deze woorden.',
    },
    5: {
        1: 'Maar over tijden en stonden, broeders, behoeft u niet te worden geschreven.',
        2: 'Want zelf weet gij goed, dat de Dag des Heren komt als een dief in de nacht.',
        3: 'Wanneer men zegt: "Vrede en veiligheid," dan valt op hen het verderf onverwacht, zoals barensweeën op een zwangere vrouw; en ontkomen doen ze zeker niet.',
        4: 'Maar gij broeders, gij verkeert niet in duisternis, zodat de Dag u als een dief zou verrassen.',
        5: 'Want allen zijt gij zonen van het licht, zonen ook van de dag; van nacht of duisternis zijn we het niet.',
        6: 'Slapen we dus niet als de anderen, maar laten we waken en nuchter blijven.',
        7: 'Want wie slapen, slapen ‘s nachts; en die zich bedrinken, bedrinken zich ‘s nachts.',
        8: 'Maar wij moeten nuchter blijven, want we zijn zonen van de dag; toegerust met het pantser van geloof en van liefde, en met de helm, de hoop op de zaligheid.',
        9: 'Want God heeft ons niet bestemd voor de Toorn, maar tot het verwerven der zaligheid door onzen Heer Jesus Christus,',
        10: 'die voor ons is gestorven, opdat we, wakend of slapend, samen met Hem zouden leven.',
        11: 'Troost dus elkander, sticht ook elkander, zoals gij gewoon zijt te doen.',
        12: 'We verzoeken u, broeders, hen te waarderen, die onder u arbeiden, die u vóórgaan, en terechtwijzen in den Heer;',
        13: 'acht ze ook meer dan gewone liefde waardig om hun arbeid. Bewaart de vrede onder elkander.',
        14: 'Broeders, we sporen u aan: berispt de leeglopers, bemoedigt de kleinmoedigen, ondersteunt de zwakken, weest jegens allen geduldig.',
        15: 'Past op, dat niemand kwaad met kwaad vergeldt; maar streeft allen het goede na jegens elkander en jegens allen.',
        16: 'Weest altijd blijde.',
        17: 'Bidt zonder ophouden;',
        18: 'brengt dankzegging voor alles; want dit is voor u Gods wil in Christus Jesus.',
        19: 'Blust den Geest niet uit,',
        20: 'versmaadt de profetieën niet;',
        21: 'maar onderzoekt alles, en behoudt het goede.',
        22: 'Onthoudt u van kwaad onder iedere vorm.',
        23: 'Dan moge de God van de vrede zelf u heiligen heel en al; uw geest, uw ziel en uw lichaam blijve ongerept bewaard en onberispelijk tot de komst van Jesus Christus onzen Heer.',
        24: 'Hij die roept, is ook getrouw; Hij zal het ook ten uitvoer brengen.',
        25: 'Bidt voor ons, broeders.',
        26: 'Groet al de broeders met een heilige kus.',
        27: 'Ik bezweer u bij den Heer, de brief aan al de broeders voor te lezen.',
        28: 'De genade van onzen Heer Jesus Christus zij met u!',
    },
}
